package com.deliverysaas.deliveries;
import java.time.Instant;import java.util.UUID;import com.deliverysaas.deliveries.domain.*;
public record DeliveryResponse(UUID id,UUID orderId,UUID driverId,UUID vehicleId,DeliveryStatus status,DeliveryPriority priority,Instant scheduledAt,Instant windowStart,Instant windowEnd,Instant pickedUpAt,Instant deliveredAt,String failureReason,Instant createdAt,Instant updatedAt){public static DeliveryResponse from(Delivery d){return new DeliveryResponse(d.getId(),d.getOrder().getId(),d.getDriver()==null?null:d.getDriver().getId(),d.getVehicle()==null?null:d.getVehicle().getId(),d.getStatus(),d.getPriority(),d.getScheduledAt(),d.getWindowStart(),d.getWindowEnd(),d.getPickedUpAt(),d.getDeliveredAt(),d.getFailureReason(),d.getCreatedAt(),d.getUpdatedAt());}}
